sys_variable_value.value:
(function() {
    var tomorrow = new GlideDateTime();
    tomorrow.addDaysLocalTime(1);

    var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
    planGr.initialize();
    planGr.setValue('employee_name', 'ATF Recovery Reassess');
    planGr.setValue('employee_id', 'ATF-014');
    planGr.setValue('state', 'active');
    planGr.setValue('joining_date', tomorrow.getValue().split(' ')[0]);
    planGr.setValue('readiness_threshold', 100);
    var planId = planGr.insert();

    // Overdue mandatory task
    var taskGr = new GlideRecord('x_1919740_dayone_0_onboarding_task');
    taskGr.initialize();
    taskGr.setValue('plan', planId);
    taskGr.setValue('task_name', 'Overdue Mandatory');
    taskGr.setValue('mandatory', true);
    taskGr.setValue('task_state', 'open');
    taskGr.setValue('est_remaining_days', 15);
    taskGr.setValue('department', 'security');
    var taskId = taskGr.insert();

    var engine = new DayOneReadinessEngine(planId);
    engine.recalculate();

    planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
    planGr.get(planId);
    var forecast = planGr.getValue('forecast_status');
    if (forecast !== 'delayed') throw new Error('Expected delayed forecast, got ' + forecast);

    // Now complete the task (simulate recovery)
    taskGr = new GlideRecord('x_1919740_dayone_0_onboarding_task');
    taskGr.get(taskId);
    taskGr.setValue('task_state', 'complete');
    taskGr.setValue('evidence_verified', true);
    taskGr.setValue('est_remaining_days', 0);
    taskGr.update();

    engine.recalculate();

    planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
    planGr.get(planId);
    var newForecast = planGr.getValue('forecast_status');
    if (newForecast === 'delayed') throw new Error('Forecast should no longer be delayed after recovery');
    gs.info('T-14 PASSED: Forecast updated after recovery from ' + forecast + ' to ' + newForecast);
})();
